<?php
use App\Core\{Validator as V};use App\Services\{StudentService as S,TranslationService};
$id=V::int($_GET['id']??'','Lesson',1);$lesson=S::lesson($student,$id);if(!$lesson||!$lesson['unlocked']){forbidden(tr('This lesson is locked.'));}
$readOnly=$lesson['enrolment_status']==='completed';$nonce=S::openLesson($student,$lesson);$required=S::requiredSeconds($lesson);$lang=TranslationService::currentCode();
$media=$lesson['media_asset_id']?'media.php?id='.(int)$lesson['media_asset_id']:null;
if(!$lesson['is_downloadable']){header('X-TLMTI-Cache: no');}
page_header('Learning content'); ?>
<div class="toolbar"><a class="btn" href="courses.php?id=<?= (int)$lesson['subject_id'] ?>">← <?= e(tr('Modules')) ?></a><span class="pill <?= $lesson['completed']?'ok':'' ?>" data-study-state><?= e(tr($lesson['completed']?'Completed':'in_progress')) ?></span></div>
<div class="learning-layout"><section class="card lesson-main" data-study data-readonly="<?= $readOnly?1:0 ?>" data-lesson-id="<?= $id ?>" data-cycle="<?= $lesson['cycle'] ?>" data-open-token="<?= e($nonce) ?>" data-required="<?= $required ?>" data-seconds="<?= $lesson['seconds'] ?>" data-completed="<?= $lesson['completed']?1:0 ?>" data-position="<?= $lesson['position'] ?>"><div class="card-heading"><h2><?= e($lesson['title']) ?></h2><span class="pill"><?= e(tr($lesson['item_type'])) ?></span></div>
<?= \App\Services\ContentImageService::thumbnail($lesson['cover_asset_id']??null,$lesson['title']) ?>
<?php if($media): ?><?php if($lesson['item_type']==='video'): ?><video controls preload="metadata" src="<?= e($media) ?>" data-study-player playsinline></video><?php elseif($lesson['item_type']==='audio'): ?><audio controls preload="metadata" src="<?= e($media) ?>" data-study-player></audio><?php elseif($lesson['item_type']==='image'): ?><img class="lesson-image" src="<?= e($media) ?>" alt="<?= e($lesson['title']) ?>"><?php else: ?><a class="btn" href="<?= e($media) ?>"><?= icon('book') ?><?= e(tr('Open learning material')) ?></a><?php endif; ?><?php endif; ?>
<article id="study-text"><?= nl2br(e($lesson['body'])) ?></article><div class="spaced"><button class="btn" data-tts-target="study-text" data-tts-lang="<?= $lang==='hi'?'hi-IN':'en-IN' ?>" aria-pressed="false"><?= icon('play') ?><?= e(tr('Listen')) ?></button><p class="muted" data-tts-notice hidden></p></div>
<div class="study-footer"><div><small class="muted"><?= e(tr('Study time')) ?>: <strong data-study-seconds><?= (int)$lesson['seconds'] ?></strong> / <?= $required ?> <?= e(tr('seconds')) ?></small><p class="status-note" data-study-message aria-live="polite"><?= e(tr('Your progress is saved automatically.')) ?></p></div><button class="btn btn-primary" data-study-complete <?= $lesson['completed']||$readOnly?'disabled':'' ?>><?= icon('check') ?><?= e(tr($readOnly?'Read only':($lesson['completed']?'Completed':'Mark complete'))) ?></button></div><noscript><p><?= e(tr('Enable JavaScript to track study time and complete lessons.')) ?></p></noscript></section>
<aside class="card"><h2><?= e(tr('Modules')) ?></h2><h3><?= e($lesson['module']['title']) ?></h3><?php foreach($lesson['module']['lessons'] as $l): ?><div class="lesson-link <?= (int)$l['id']===$id?'current':'' ?>"><?= icon($l['completed']?'check':($l['unlocked']?'play':'lock')) ?><?php if($l['unlocked']): ?><a href="lesson.php?id=<?= (int)$l['id'] ?>"><?= e($l['title']) ?></a><?php else: ?><span><?= e($l['title']) ?></span><?php endif; ?></div><?php endforeach; ?><a class="btn full-width spaced" href="tests.php?subject_id=<?= (int)$lesson['subject_id'] ?>"><?= icon('test') ?><?= e(tr('Tests')) ?></a></aside></div>
<?php page_footer();
